class ArtifactEntry(BaseModel):
    """Pydantic v2 model for individual artifact metadata with validation."""
    filename: str = Field(
        ...,
        min_length=1,
        pattern=r'^[a-zA-Z0-9_./\\\-]+$',
        description="Relative path of the artifact within ARTIFACTS_DIR"
    )
    status: ArtifactStatus = Field(
        default=ArtifactStatus.PENDING,
        description="Current pipeline status"
    )
    size: int = Field(
        default=0,
        ge=0,
        description="File size in bytes"
    )
    checksum: Optional[str] = Field(
        default=None,
        pattern=r'^[a-f0-9]{64}$',
        description="SHA-256 hex digest of file contents"
    )
    created_at: Optional[str] = Field(
        default=None,
        description="ISO 8601 timestamp of first discovery"
    )
    updated_at: Optional[str] = Field(
        default=None,
        description="ISO 8601 timestamp of last modification"
    )
    notes: Optional[str] = Field(
        default=None,
        max_length=1000,
        description="Optional human-readable notes"
    )

    @field_validator('filename')
    @classmethod
    def validate_filename_safety(cls, v: str) -> str:
        """Prevent path traversal attacks in artifact keys."""
        if '..' in v:
            raise ValueError(f"Path traversal detected in filename: {v}")
        if v.startswith('/') or v.startswith('\\'):
            raise ValueError(f"Absolute path detected in filename: {v}")
        # Normalize path separators
        normalized = v.replace('\\', '/')
        return normalized

    @field_validator('status')
    @classmethod
    def validate_status_enum(cls, v: ArtifactStatus) -> ArtifactStatus:
        """Ensure status is a valid ArtifactStatus enum member."""
        if not isinstance(v, ArtifactStatus):
            raise ValueError(f"Invalid status type: {type(v).__name__}")
        return v

    @field_validator('checksum')
    @classmethod
    def validate_checksum_format(cls, v: Optional[str]) -> Optional[str]:
        """Ensure checksum is lowercase hex if provided."""
        if v is not None:
            return v.lower()
        return v

    class Config:
        """Pydantic v2 configuration."""
        frozen = False  # Allow mutation for status updates
        use_enum_values = True  # Serialize enum as string
        extra = 'forbid'  # Reject unknown fields


